class Solution { public: bool checkMove(vector<vector<char>>& board,int rMove,int cMove,char color){char opponent=color=='B'?'W':'B';for(int rowStep=-1;rowStep<=1;++rowStep)for(int colStep=-1;colStep<=1;++colStep){if(!rowStep&&!colStep)continue;int row=rMove+rowStep,col=cMove+colStep,count=0;while(row>=0&&row<(int)board.size()&&col>=0&&col<(int)board[0].size()&&board[row][col]==opponent){++count;row+=rowStep;col+=colStep;}if(count&&row>=0&&row<(int)board.size()&&col>=0&&col<(int)board[0].size()&&board[row][col]==color)return true;}return false;} };
